insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-issuer-tags-registered-empty-s684','decision','Five new issuers registered with no tag and no acronym','S684 conductor: tests/issuer_tags.test.js was red on main. The five issuers came from Sam''s own saves of 2026-11-18 (reviewed_by on 18 of 20 rows). Registered in kb/reference/issuer_tags.json with no tag and no acronym, matching as an absent issuer does. AATA''s acronym and whether the three high schools stay issuers are the curation session''s.',array['issuers','credentials','main-red'],'proposed','#3544; kb/reference/issuer_tags.json','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('d-ccsf-comm-cmst-kept-again-s684','decision','CCSF COMM for CMST prefix alias kept as the fallback again','S684 conductor: S683''s re-read of CCSF 43116 prints COMM 38, and on the filed list the course-id route reproduces 38 of the COMM for CMST pair''s 39 matches, so under the S653 rule the alias stays (kb/program_requirements_reconcile.json, kept_again note). Plan rebuilt: 6 retire, 11 stay; tests/course_id_route_test.py updated.',array['program-requirements','prefix-alias','ccsf'],'proposed','#3544','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('d-skip-preview-under-ceiling-s684','decision','Reread previews skipped where the plan''s ceiling is under $1.70 a college','S684 conductor: after Ventura the lane-2 reread previews were skipped; the plan''s ceiling sits under $1.70 a college, and the workflow''s $40 gate stays on every paid run.',array['program-requirements','reread','cost'],'proposed','claude/reread-wave-s684','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('d-post-on-reviewed-head-before-merge-s684','decision','Reread posts ran on #3547''s reviewed head before its merge','S684 conductor: "posts go" at 11:45Z used keep-the-better from #3547''s reviewed head cbbd0e0f on its branch (lints green), while its CI finished; #3547 merged 11:58Z as 94a02499. Keeps the lane moving when a reviewed fix waits only on CI.',array['program-requirements','reread','conductor'],'proposed','#3547','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('d-no-display-tonight-s684','decision','The display build held for one run next session','S684 conductor: kb/_build_roep_display.py and step=display not run: an hour-long two-step apply with a live count gate, to be kept clear of the 12:17Z daily slot, on a runner pool where every job waited ten minutes, and the night''s records would make it stale by morning. The next session builds once with every record.',array['program-requirements','display','conductor'],'proposed','docs/session_685_handoff.md','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('d-no-second-update-behind-a-docs-checkpoint-s684','decision','No second update from main when only a docs checkpoint landed','S684 conductor: #3528 merged one docs checkpoint (#3535) behind main. #3535 touched none of #3528''s files, so no second update from main and no second CI run before the merge.',array['conductor','merge','ci'],'proposed','#3528; #3535','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('d-two-rounds-then-ship-the-verified-part-s684','decision','Two review rounds, then ship the verified part','S684 conductor (#3547): the round-two finding refuted the first fix for the second-pass case, so the unverified branch was removed and the open item went to COBIx in the docstring, the PR body and comment 7007297442. COBIx agreed it need not block. A third round on one finding is not run.',array['conductor','review','program-requirements'],'proposed','#3547','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('d-live-read-through-the-migrate-runner-s684','decision','A read whose values feed a write goes through the migrate runner''s receipt','S684 conductor: a live read whose values feed a write runs through supabase-migrate.yml, its SQL generated and its receipt parsed by script, so no model copies the values. The receipt keeps 4,000 characters, so the query returns counts and differences only (run 44514885539).',array['supabase','rule-10','procedure'],'proposed','claude/s684-live-read','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('p-lints-stops-at-first-failure-s684','pitfall','lints stops at its first failure, so a red main hides the next','S684: the lints job stops at its first failing step. With tests/issuer_tags.test.js red, tests/course_id_route_test.py failed unseen behind it. Before a repair push run the remaining steps locally (a scratch script ran 164 steps in about 8 minutes).',array['ci','lints','main-red'],'proposed','docs/reference/conductor_mode.md','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('p-control-number-leading-zero-s684','pitfall','A control number as a number, or without its leading zero, skipped both guards','S684, #3547 second reader: keep-the-better took a control number as a number or without its leading zero, and both guards skipped it. Fixed: five ASCII digits, strings only. All 18,980 committed records carry five digits.',array['program-requirements','control-number','reread'],'proposed','#3547','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('p-hung-size-jobs-starve-the-pool-s684','pitfall','Hung Repo size guard jobs held runners for hours','S684: each PR push started a Repo size guard / size job that hung for hours (about 6, #3543''s finding); a couple of dozen held runners, so every job waited ten minutes and more. #3543 fixes it (merged as f869acfe). Cancelling hung runs is Sam''s to allow.',array['ci','runner-pool','repo-size'],'proposed','#3543','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('p-branch-update-starts-read-only-workflows-s684','pitfall','Updating PRs from main re-triggers the census and capture workflows','S684: updating #3535 and #3528 from main at once, with three workers'' dispatches and two new PRs, queued CI and the database runs 15 minutes and more. After the wave changed their scripts, each update from main re-triggers the census and capture workflows. Update one PR at a time, right before its merge.',array['ci','runner-pool','merge'],'proposed','docs/reference/conductor_mode.md','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('p-migrate-receipt-keeps-4000-chars-s684','pitfall','A migrate receipt keeps only 4,000 characters of a response','S684: the live read through the migrate runner (run 44511382865) was cut off, since the receipt keeps 4,000 characters of a response. Write the query to return counts and only the differences (run 44514885539 did).',array['supabase','receipts','migrate'],'proposed','claude/s684-live-read','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('p-cobix-watch-misses-on-search-lag-s684','pitfall','The COBIx watcher can miss a comment when GitHub search lags','S684: COBIx''s 11:06Z comment on #3547 (7007316438) never arrived as a watcher event; GitHub search lagged its index past the watcher''s two-minute overlap. pr-gate''s thread read caught it. Read a PR''s thread before merging it whatever the watcher reports.',array['cobix','watcher','conductor'],'proposed','#3547','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('p-ci-log-tails-fill-the-context-s684','pitfall','CI log reads filled the conductor''s context','S684: 640,341 of 786,077 tokens were used by 12:00Z, most on large CI log reads and worker notices. Read a failed job''s log with tail_lines 15, and gate through pr-gate, never get_check_runs.',array['conductor','context','ci'],'proposed','docs/reference/conductor_mode.md','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('f-reread-drops-files-live-rows-stay-s684','fact','A reread at a single-PDF catalog drops record files while live rows stay','S684: at single-PDF catalogs rule A set 23 of 27 aim records not_found and the filing dropped their failing record files (LA City 2, Canada 1, Solano 7, Shasta 13 at 11:31Z; none passed live). S683''s wave took 160 such files off main. Live rows stay; under live_runs a later re-read of one is held for a person. Rule D and the discontinued capture label them.',array['program-requirements','reread','records'],'proposed','docs/program_requirements_harvest_lessons.md','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('f-courseleaf-generic-heading-restores-good-rereads-s684','fact','A generic CourseLeaf heading passes the own-program test','S684: CourseLeaf pages head their lists REQUIREMENTS, Course List, Major Requirements or Requirements, so keep-the-better''s own-program test restored 17 re-reads that had placed courses on the heading alone: Ventura 4, Evergreen Valley 13 (all 13 pass). Fix: accept a re-read whose page is the program''s own by URL or page title when the heading is generic, then re-post the 17.',array['program-requirements','reread','courseleaf'],'proposed','claude/reread-wave-s684','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('m-main-repaired-wave-merged-s684','milestone','main repaired; the S683 wave, its checkpoint and #3528 merged','S684: commit 757fbb1d repaired the issuer and course-id route tests; #3544 (the S683 wave) merged 10:48Z as 8baace0f, #3535 (S683''s checkpoint) 11:24Z as 09e5c0d1, #3528 11:32Z as 1ad7ae80. S683''s 19 memory rows applied (migrate run 44506909495).',array['main-red','merge','milestone'],'proposed','#3544; #3535; #3528','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('m-keep-better-guard-merged-s684','milestone','Keep-the-better''s guard merged (#3547)','S684: #3547 merged 11:58Z as 94a02499 after two review rounds: keep-the-better reads the checked list first, holds a live run main lacks (live_runs), and takes only five-digit control numbers. Two items stay open for COBIx: the second pass after a post, and the generic CourseLeaf heading.',array['program-requirements','reread','milestone'],'proposed','#3547','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('m-named-gaps-reread-applied-s684','milestone','Named gaps applied over the S683 re-read records (#3548)','S684: 2 rows labeled, Santa Rosa Junior 44788 no_units_read and CCSF 41049 catalog_figures_differ. Pre-read 44513271094 (listed 2, matched 2, checked 0), apply 44515993146 returned 2, none skipped; rollback beside the plan on #3548 (head 8e30736c).',array['program-requirements','named-gaps','milestone'],'proposed','#3548','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('m-siskiyous-outlines-loaded-s684','milestone','College of the Siskiyous outlines loaded, 366 rows','S684: full read 44508568959 (315 of 315 pages; outcomes on 247, objectives on 119), standing test 26 of 26, load 44512255004 inserted 366 rows (247 slo, 119 objective), kept 0, held 0, error null. Receipt kb/receipts/course_outcomes_siskiyous_44512255004.json on claude/slo-college_of_the_siskiyous (9769a585). 68 pages print no outcomes.',array['course-outcomes','slo','milestone'],'proposed','claude/slo-college_of_the_siskiyous','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('d-commons-build-to-a-plain-session-s684','decision','The CPL Commons page build goes to a plain session','S684 conductor: COBIx on #3533 (comment 7006930860) relayed Sam''s ask of 2026-11-19 4:28 AM PT to build the CPL Commons front page now. Not started: Sam''s routine prompt of 2026-11-17 keeps conductor runs to collection, and the run was at 88% of its context. Sam told by phone notice about 12:37Z; COBIx on #3533. A routine firing needs Sam''s word before starting it.',array['commons','conductor','cobix'],'proposed','docs/session_685_handoff.md','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('p-commons-data-status-not-in-check-generated-s684','pitfall','check_generated.sh does not run the Commons data status check','S684: #3548''s two new gap labels left kb/status/commons_data.json stale (collected_with_gaps 93 to 95); lints failed on tests/commons_data_status_build_test.py --check while check_generated.sh reported all current. Rebuilt with its builder (head 0ed76d1c). Run that test after any record write.',array['ci','commons','generated-files'],'proposed','#3548','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('m-reread-batch-ten-colleges-s684','milestone','The second reread batch: ten colleges, 87 replaced, 42 inserted','S684: Ventura, Canada, Los Angeles City, Evergreen Valley, Solano, Shasta, Santa Barbara City, Victor Valley, Ohlone, Clovis; every receipt error null; $16.08 paid. Kept 114, restored 24, new 22, held 2 (Ventura 45355, Shasta 18153); 87 rows replaced, 42 inserted; 67 record files dropped, none passing live. program_requirement_records 18,312 to 18,354.',array['program-requirements','reread','milestone'],'proposed','claude/reread-wave-s684; -b; -c','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('m-crafton-hills-outlines-loaded-s684','milestone','Crafton Hills outlines loaded, 1,123 rows','S684: trial 44508733573 (12 of 12), full read 44509906805 (566 of 566 pages; outcomes on 557, objectives on 566), standing test 26 of 26, load 44522694613 inserted 1,123 (557 slo, 566 objective), kept 0, held 0, error null. Branch claude/slo-crafton_hills (be26092b). course_outcomes 33,836 at 12:36Z.',array['course-outcomes','slo','milestone'],'proposed','claude/slo-crafton_hills','SkyVerdin (S684), the conductor',null,'SkyVerdin (S684)',date '2026-11-19'),
('sam-one-credential-list-2026-11-19','decision','One credential list; exhibits are its children (Sam, Nov 19)','Sam with COBIx, 2026-11-19, 1 to 2:45 AM PT, relayed by COBIx on #3533 (comment 7006905282), in paraphrase: one credential list under a stable COBI id; a MAP exhibit is one evaluation of a credential; a link table replaces title joins; a ctdl_id field, with no bulk pull of Credential Engine ids yet. Commons and CDC merge into one page; the one-ETA reversal is pending.',array['credentials','exhibits','ctdl','commons'],'proposed','docs/kb-notes/adr-one-credential-list-exhibits-are-its-children.md','Sam Lee, relayed by COBIx on #3533',null,'SkyVerdin (S684)',date '2026-11-19')
